"""Component layers.15.mlp.down_proj:5696: an "of" detector.

The component fires on the word "of" when it follows a noun. On average "of" gives about 4.6,
more after quantity and part-of-a-whole words ("all of", "many of", "one of", "a portion of",
"the number of", "a fraction of"), and much less in fixed or adverbial phrases ("instead of",
"because of", "out of", "as of"), or when "of" follows a copula ("is part of"). A few linking
words also fire a little: "with", "that", "who", "which", "like", "such", and the foreign
prepositions "de", "du", "mit", "di". Every other token gets 0. The rest of its variance (noise
on most tokens, and spread within "of") is not described by these words.

The program looks back at most two words, within the same document, so it is causal.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Quantifiers and words for a part, portion, amount or collection of something.
QUANTITY = {
    "all", "any", "some", "many", "most", "each", "both", "either", "none", "few",
    "several", "one", "two", "three", "half", "rest", "majority",
    "part", "parts", "portion", "portions", "fraction", "percentage", "proportion",
    "percent", "piece", "pieces", "subset", "member", "members", "group", "groups",
    "element", "elements", "component", "components", "number", "numbers", "amount",
    "set", "sets", "kind", "kinds", "type", "types", "form", "forms", "version",
    "snippet", "sum", "series", "lot", "lots", "bunch", "couple", "handful", "bulk",
    "variety", "array", "vector",
}

# Words after which "of" is fixed or adverbial, so it fires weakly.
FIXED_BEFORE_OF = {
    "instead", "because", "out", "due", "instance", "as", "regardless", "ahead",
    "inside", "outside", "off", "away",
}

# Words before the noun that makes "of" a predicate ("is part of", "are one of").
COPULAS = {"is", "was", "are", "were", "be", "as"}

# Linking words, and their typical activation.
LINKING = {
    "with": 1.4, "that": 1.2, "who": 1.8, "which": 0.7, "like": 1.5, "such": 1.2,
    "whose": 2.3, "de": 2.4, "du": 2.4, "des": 1.4, "der": 1.3, "mit": 2.5, "di": 1.9,
    "del": 1.6, "que": 1.3,
}


def word(token: str) -> str:
    """A token as a lowercase word, with its leading space removed."""
    return token.strip().lower()


def step(carry, prefix, upstream: Mapping):
    words, docs = prefix.token_strings, prefix.document_ids
    current = len(words) - 1

    def back(k: int) -> str:
        """The word k tokens before the current one, or '' across a document boundary."""
        i = current - k
        if i < 0 or docs[i] != docs[current]:
            return ""
        return word(words[i])

    w = word(words[current])
    if w == "of":
        prev = back(1)
        if prev in FIXED_BEFORE_OF:
            return carry, 1.0
        value = 4.6
        if prev in QUANTITY:
            value += 0.9
        if back(2) in COPULAS:
            value -= 1.0
        return carry, value
    return carry, LINKING.get(w, 0.0)

"""Layer 15, MLP hidden unit 5697 (the component reads mostly that unit).

A negative-going feature, near zero on most tokens. It dips on function words that
open a phrase in German text (der, die, das, den, auf, mit, für, zu, ...), by far the
most when the passage is German (3+ German function words in the last 20 tokens), and
least right after punctuation, "und", "oder" or "dass". It also dips on Chinese
function words (对, 与, 和, 在, ...) and Japanese particles (の, 、, は, を, ...), on
"the / a / this" right after a wh-word ("what the", "which the", "where the"), and a
little on any other word inside a German passage. This captures only a few percent of
the variance: the largest negative spikes are not explained by any simple rule here.
"""

READS = ()

GERMAN_ARTICLES = {"der", "die", "das", "den", "dem", "des", "ein", "eine", "einen", "einem", "einer", "eines"}
GERMAN_PREPOSITIONS = {"zu", "zur", "zum", "auf", "mit", "für", "von", "aus", "bei", "nach", "über", "unter", "durch", "vor", "im", "um", "als", "gegen", "ohne", "wie"}
GERMAN_WORDS = GERMAN_ARTICLES | GERMAN_PREPOSITIONS | {"und", "oder", "aber", "nicht", "auch", "noch", "nur", "sich", "wird", "sind", "ist", "haben", "werden", "kann", "wir", "sie", "er", "es", "ich", "uns"}
CHINESE_FUNCTION = set("对与和在为以及于将被把从向")
JAPANESE_PARTICLES = {"の", "、", "は", "に", "を", "が", "で", "と", "も", "へ"}
ENGLISH_DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "each", "every", "some", "all", "such", "my", "your", "his", "her", "its", "their", "our", "no"}
CLAUSE_START = {".", "!", "?", ":", ";", "\n", "", '"', ",", "und", "oder", "dass", "daß"}
WH_WORDS = {"what", "which", "whom", "whose", "how", "where", "when", "why", "if", "as", "once", "whenever", "while", "whether", "who"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    # the last 20 tokens of this document, the current one included
    same_doc = [d == prefix.document_ids[-1] for d in prefix.document_ids[-20:]]
    words = [w.strip().lower() for w in prefix.token_strings[-20:]]
    window = [w for w, s in zip(words, same_doc) if s]
    german = sum(w in GERMAN_WORDS for w in window) >= 3
    previous = words[-2] if len(words) > 1 and same_doc[-2] else ""

    if word in GERMAN_ARTICLES or word in GERMAN_PREPOSITIONS:
        if not german:
            value = -0.7
        elif previous in CLAUSE_START:
            value = -1.5
        else:
            value = -4.5
    elif word in CHINESE_FUNCTION:
        value = -2.0
    elif word in JAPANESE_PARTICLES:
        value = -1.2
    elif word in ENGLISH_DETERMINERS and previous in WH_WORDS:
        value = -1.8
    elif german:
        value = -1.0
    else:
        value = 0.0
    return carry, value

"""Object pronouns and object nouns in English prose, at the end of a verb phrase.

Component p-82af68dd@100000/layers.15.mlp.down_proj:5709 writes a signed, diffuse
signal into the residual stream. Its strongest positive values sit on the word that
completes a verb's or preposition's object: "read IT", "bring THEM", "for HIM",
"retake the TEST", "pay TAXES". Verbs, function words and code are near zero or below.

This program predicts the activation from a few word-level facts a reader can check:
  * an object pronoun (them, him, it, us, me, her) that follows a word, not a clause
    opener like "and", "if" or a comma (so "it" as a subject scores 0);
  * a noun, and especially a plural noun, after a determiner or on its own;
  * closing marks of code or quotes (")", "`", quote marks, a trailing "s");
  * function words (the, of, is, a comma, a full stop), which sit slightly below average.
Anything else gets the average activation of about 0.2.

It explains only a few percent of the variance: the component's activation is
spread over almost every token, and a table of token means would do better (about 8%)
without being readable.
"""

import re
from functools import lru_cache

import wordnet

READS = ()
PRONOUN_VALUE = {"them": 5.0, "him": 3.7, "it": 2.4, "us": 0.8, "me": 0.8, "her": 0.8}
# words after which an object pronoun is a subject instead, or is not an object at all
CLAUSE_OPENERS = {
    "and", "or", "if", "so", "then", "but", "that", "when", "because", "as", "while",
    "which", "who", "what", "where", "how", ",", ".", ";", ":", "!", "?", "(", '"', "'", "",
}
DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "your", "my", "his", "her", "its",
    "our", "their", "every", "each", "some", "any",
}
FUNCTION_WORDS = {",", ".", "the", "of", "is", "and", "in", "to", "a", "that", "for", "with"}
CLOSERS = {")", "`", '"', "”", "s"}
BASE = 0.2


@lru_cache(maxsize=None)
def is_noun(word):
    return bool(re.fullmatch(r"[a-z]+", word)) and "noun" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    i = prefix.position
    word = prefix.token_strings[-1].strip().lower()
    same_doc = i > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if word in PRONOUN_VALUE and prev not in CLAUSE_OPENERS:
        return carry, PRONOUN_VALUE[word]
    if word in CLOSERS:
        return carry, 1.4
    if word in FUNCTION_WORDS:
        return carry, -0.2
    if is_noun(word):
        if word.endswith("s") and len(word) > 3 and not word.endswith("ss"):
            return carry, BASE + 0.9
        if prev in DETERMINERS:
            return carry, BASE + 0.4
        return carry, BASE + 0.1
    return carry, BASE

"""Disjunction detector: fires on the word "or" (and its equivalents in other
languages) when it joins two alternatives in running text, e.g. "tea or coffee",
"oder", "ou", "или", "或者". Predicts about 4.3 there, about 2.5 for "or"-like
forms (capitalised, "nor", "/or"), and 0 everywhere else."""

READS = ()

LEADING_SPACE_OR = {  # the word for "or" written as a separate word, lowercase
    " or", " oder", " ou", " или", " أو", " او", " 或", " 或者", " 或是", " vagy", " atau",
    " eller", " hoặc", " veya", "或者", "或是", "或", "または", "あるいは", "또는", "이나", "거나",
}
WEAKER_OR = {" Or", " OR", "Or", "/or", "-or", "_or", " nor", " ó", " lub", " sau", " Alternatively"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in LEADING_SPACE_OR:
        value = 4.3
    elif tok in WEAKER_OR:
        value = 2.5
    else:
        value = 0.0
    return carry, value

"""Stance verbs of knowing, believing and perceiving, said by the speaker about themselves:
"I know", "I think", "I'm sure", "I can see", "we understand". The component reads the verb
itself and fires on that token. It is strongest when "I" starts a main clause ("... . I know
this", "But I understand"), weaker when "I" sits in an if/when clause or a question, and weaker
still for the same verbs after another subject ("you know", "he knew"). A little of its
activation falls on the clause opener that follows ("I know *that*"), on hedges like "maybe" and
"probably", and on the Chinese equivalents of "know" and "think".
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# typical activation of each verb straight after a main-clause "I"
FIRST_PERSON = {
    "know": 28, "knew": 20, "understand": 20, "understood": 15, "remember": 18, "realize": 14,
    "believe": 14, "think": 13, "see": 15, "hope": 12, "recognize": 12, "sure": 20, "certain": 12,
    "confident": 14, "aware": 14, "heard": 10, "hear": 10, "notice": 10, "noticed": 10,
    "feel": 7, "felt": 7, "guess": 7, "assume": 7, "suspect": 7, "doubt": 7, "imagine": 7,
    "thought": 5, "wonder": 6, "agree": 8, "glad": 12, "sorry": 8, "grateful": 8,
}
OTHER = 2.0  # the same verbs after another subject
HEDGE = {"maybe": 2.5, "perhaps": 2.5, "probably": 3.0, "obviously": 4.0, "surely": 4.0,
         "apparently": 3.0, "definitely": 2.5, "hopefully": 4.0, "seems": 2.0}
CHINESE = {"知道": 10, "我知道": 20, "都知道": 18, "不知道": 5, "了解": 5, "理解": 4,
           "认为": 4, "觉得": 6, "我觉得": 10, "相信": 8, "我相信": 20}
FIRST = {"i", "we"}
AUX = {"am", "'m", "’m", "do", "don't", "don’t", "can", "could", "would", "will", "must",
       "still", "just", "really", "not", "also", "always", "never", "'ve", "’ve", "have", "had"}
# words that open an if/when clause or a question, before which "I" is subordinate
SUBORDINATE = {"if", "when", "as", "do", "did", "what", "where", "how", "whether", "who"}
COMPLEMENT = {"that", "what", "how", "why"}  # the clause opener after such a verb


def word(s):
    """A token's word: its letters, without the quote, bracket or space stuck to it."""
    return s.strip().lstrip("\"“‘'(").lower()


def step(carry, prefix, upstream: Mapping):
    strings = prefix.token_strings[-4:]
    words = [word(s) for s in strings]
    if len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        words[:-1] = [""] * (len(words) - 1)  # a new document starts here
    w = words[-1]
    prev = words[-2] if len(words) >= 2 else ""
    prev2 = words[-3] if len(words) >= 3 else ""
    prev3 = words[-4] if len(words) >= 4 else ""
    if w in FIRST_PERSON:
        if prev in FIRST or (prev2 in FIRST and prev in AUX):
            before_i = prev2 if prev in FIRST else prev3
            if before_i in SUBORDINATE:
                return carry, 0.3 * FIRST_PERSON[w]
            return carry, float(FIRST_PERSON[w])
        return carry, OTHER
    if w in HEDGE:
        return carry, HEDGE[w]
    if prev in FIRST_PERSON and w in COMPLEMENT:
        return carry, 6.0
    if prefix.token_strings[-1].strip() in CHINESE:
        return carry, float(CHINESE[prefix.token_strings[-1].strip()])
    return carry, 0.0

"""Layer 15, MLP hidden unit 5732 (the component reads almost only this unit).

The unit goes strongly negative in "part of a whole" phrases, where the next word
will name the whole: "X out of [N]", "page 3 of [N]", "one of [the]", "a portion of
[the]", "7.1 / [10]", "the first of [the]". It is most negative on the word that
introduces the whole ("of" after "out"), and on the first word of the whole after
"of" ("the", or a digit). Elsewhere it is near zero, with small dips on prepositions
and possessive determiners.
"""

READS = ()

NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}
# words that name a part, share or count of something ("one of", "percent of", "out of")
PART_WORDS = {
    "out", "one", "two", "three", "four", "five", "first", "second", "third", "last",
    "half", "quarter", "percent", "%", "portion", "part", "few", "most", "best", "worst",
    "which", "stage", "phase", "aspect", "some", "many", "each", "all", "fraction",
    "majority", "subset", "share", "cent",
}
DETERMINERS = {"the", "this", "that", "their", "its", "his", "her", "your", "our", "a", "an"}
POSSESSIVES = {"his", "her", "its", "their", "your", "our", "this", "these"}
PREPOSITIONS = {"of", "Of", "in", "from", "among", "amongst", "on", "within", "across", "inside"}


def is_number(text):
    text = text.strip()
    return text.isdigit() or text.lower() in NUMBER_WORDS


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    toks = prefix.token_strings
    n = len(toks)

    def back(k):
        # the token k places before the one being predicted, within the same document
        i = n - 1 - k
        if i < 0 or docs[i] != docs[-1]:
            return ""
        return toks[i].strip()

    cur = toks[-1].strip()
    p1, p2, p3 = back(1), back(2), back(3)
    if cur in ("of", "Of"):
        if p1 == "out" and is_number(p2):
            return carry, -47.0  # "8 out of"
        if is_number(p1):
            return carry, -6.0  # "page 3 of"
        if p1 in PART_WORDS:
            return carry, -3.3  # "one of", "portion of"
        return carry, -0.7
    if p1 in ("of", "Of") and cur in DETERMINERS and p2 in PART_WORDS:
        return carry, -4.5  # "one of the"
    if p1 == "of" and cur == "" and (is_number(p2) or p2 in PART_WORDS):
        return carry, -24.0  # the space before a digit in "3 of [ ]10"
    if cur == "/" and is_number(p1):
        return carry, -3.9  # "7.1 /" rating or fraction
    if cur == "the" and p1 in PREPOSITIONS:
        return carry, -1.2
    if cur in ("among", "from"):
        return carry, -3.2 if cur == "among" else -0.45
    if cur in POSSESSIVES:
        return carry, -0.4
    return carry, 0.0

"""Layer 15 MLP unit 5736 (a component of down_proj), as a word-level rule.

What the component is: its activation is (almost exactly) the MLP hidden unit 5736 of
layer 15, scaled by how far that unit writes into the residual stream. Its activation is
mostly context-dependent: the same word can be strongly negative in one phrase and
positive in another. Even so, a few word-level tendencies are consistent in training text:

- "with" is negative, most strongly after words about dealing with people
  ("interact with", "connect with", "work with", "relationship with", "contact with").
- "you"/"your" is positive, most strongly as the subject of a clause that opens with
  if/when/unless/as/because/once/and/but (e.g. "If you ...", "so you can ...").
- "make"/"makes"/"made" is positive (as in "makes you feel", "make sure").
- "to" is negative after relational nouns and evaluative adjectives ("access to",
  "exposure to", "important to", "easy to") and positive after verbs of intention
  ("decided to", "began to", "ready to", "wish to").
- Everything else sits near the average, about +0.04.

This captures only a small part of the variance: the component is mostly driven by
context that a word list cannot see. The numbers are group means measured on training
text. The program is causal: it looks only at the current word and the one before it.
"""

READS = ()

BASE = 0.04
SOCIAL_WITH = {
    "connect", "interact", "interaction", "communicate", "relationship", "working",
    "work", "contact", "share", "play", "love", "association", "meet", "time",
}
CLAUSE_OPENERS = {
    "if", "unless", "when", "as", "because", "once", "since", "whether", "until",
    "then", "but", "and", "or", ",",
}
NEG_TO_PREVIOUS = {
    "access", "exposure", "connection", "connect", "transition", "talk", "visit",
    "important", "easy", "safe", "impossible", "nice", "fun", "obvious", "reason",
    "place", "distance", "duty", "obligation",
}
POS_TO_PREVIOUS = {
    "decided", "began", "begin", "started", "ready", "sure", "wish", "looking",
    "remember", "forget", "order", "continued", "prepared", "wait", "excited",
    "elected", "pursuant", "entitled",
}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    now = word(prefix.token_strings[-1])
    same_document = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = word(prefix.token_strings[-2]) if same_document else ""
    if now == "with":
        value = -1.45 if before in SOCIAL_WITH else -0.45
    elif now in ("you", "your"):
        value = 0.87 if before in CLAUSE_OPENERS else 0.44
    elif now == "to":
        if before in NEG_TO_PREVIOUS:
            value = -1.04
        elif before in POS_TO_PREVIOUS:
            value = 0.55
        else:
            value = 0.0
    elif now in ("make", "makes", "made", "making"):
        value = 0.67
    else:
        value = BASE
    return carry, value

"""Layer 15 MLP neuron 5741 (the down_proj component 5741): a "something is about to be
listed or quoted" detector.

Its output pushes the model toward a colon (":") as the next token, so it is active where
the text is about to introduce a list, a quoted statement, an example or a result:
"the following", "as follows", "here's the result of", "wrote in", "include, for example".

It fires most strongly on the announcing word itself: "following", "follows", "follow" and
their translations ("以下", "如下", "siguiente", ...). It is weaker on the word after such an
announcement ("the following [list]", "as follows [:]"), on "the" in "Here's the", and on
"Here" and a few reporting or enumeration words ("said", "stated", "include").
Everywhere else it predicts 0.

The values are the average activation of each cue class over training text.
"""

READS = ()

ANNOUNCE = {
    " following", " follows", " follow", " fol", "following", "follow", "Follow",
    "以下", "如下", "下列", " siguiente", " siguientes", " sau", " след", "ующ",
}
HERE = {" Here", "Here", " here"}
IS = {"'s", "’s", " is", " are"}
REPORT = {
    " said", " stated", " states", " wrote", " says", " stating", " writes",
    " include", " includes", " including", " example", " Examples",
}


def step(carry, prefix, upstream):
    """Activation at the newest token, from the words just before it."""
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    if cur in ANNOUNCE:
        value = 9.0
    elif prev in ANNOUNCE:
        value = 4.0
    elif cur == " the" and prev in IS and prev2 in HERE:
        value = 5.0
    elif cur in HERE:
        value = 1.0
    elif prev in HERE:
        value = 2.8
    elif cur in REPORT:
        value = 0.3
    else:
        value = 0.0
    return carry, value

"""Aim detector (v4): a small set of words that open an aim or purpose, such as 'in order to',
'an effort to', 'for the sake of'. The program predicts a positive value on those words and a
slightly negative value on the 'to' of forced or achieved actions ('managed to', 'forced to').
Everywhere else it predicts the component's typical resting value, about -0.04.

Measured on the cached sample, these rules explain almost none of the variance (R2 ~ 0): the
component is mostly diffuse noise, and its large positive spikes are only partly in aim frames."""
READS = ()

REST = -0.04
# nouns and verbs of effort, intent and need: the 'to' / 'for' / 'of' after them opens an aim
AIM_WORDS = {"order", "effort", "attempt", "attempts", "aim", "aimed", "sake", "desire", "meant",
             "intended", "trying", "try", "tried", "tries", "necessary", "required", "purpose",
             "goal", "search", "looking", "bid", "quest"}
# verbs after which 'to' marks a forced, decided or achieved action rather than an aim
OUTCOME_WORDS = {"managed", "forced", "decided", "unable", "free", "thanks", "came", "plan", "dedicated"}
MARKERS = {"to", "for", "of"}


def step(carry, prefix, upstream):
    i = prefix.position
    cur = prefix.token_strings[i].strip().lower()
    if cur in ("为了", "為了"):  # 'in order to' written as one Chinese word
        return carry, 1.5
    if i == 0 or prefix.document_ids[i - 1] != prefix.document_ids[i]:
        return carry, REST
    prev = prefix.token_strings[i - 1].strip().lower()
    if cur == "order" and prev == "in":
        return carry, 0.6
    if cur == "sake":
        return carry, 1.3
    if cur in MARKERS:
        if prev == "sake":
            return carry, 2.0
        if prev in AIM_WORDS:
            return carry, 0.5
        if prev in OUTCOME_WORDS:
            return carry, -0.3
    return carry, REST

"""A coarse, readable guess at the component's activation from the current token's kind.

The component is a dense linear readout of layer 15's MLP hidden units with no clear
concept behind it. The only consistent tendencies found on sampled text are weak:
chat/think markers (<think>, <|im_start|>, <tool_call>) lean positive, digits lean
slightly negative, and whitespace and punctuation lean slightly positive. Everything else
is predicted as zero. This explains well under 1% of the variance.
"""

import re

READS = ()


def kind(s):
    t = s.strip()
    if t == "":
        return "space"
    if re.fullmatch(r"<[^>]*>", t) or t.startswith("<|"):
        return "marker"
    if t.isdigit():
        return "digit"
    if re.fullmatch(r"[^\w\s]+", t):
        return "punct"
    return "other"


MEAN = {"marker": 0.1, "digit": -0.03, "space": 0.03, "punct": 0.02}


def step(carry, prefix, upstream):
    return None, MEAN.get(kind(prefix.token_strings[-1]), 0.0)

"""Layer 15 MLP hidden unit 5753 (the component's main neuron), read as a few word-level signals.

The component's activation is a read of one MLP hidden unit: layer 15's hidden unit 5753 (the
component reads it with weight 0.835, output scale ~1.05). That unit alone carries about half
of the activation's variance; the rest comes from many small units. Where the component is
important (the harvest's high-causal-importance positions) it is nearly always strongly
negative.

This program predicts it from the current token and the one before, with four signals:
  - commas (ASCII or full-width) are mildly negative;
  - the token right after a distributive quantifier ("each", "every", "每个", "per", "map")
    is negative, most strongly after "Each" and "每个";
  - Chinese time/condition particles (时, 后, 而, 就是, ...) are negative;
  - discourse connectives that open a conclusion ("So", "Thus", "Therefore", "although")
    are mildly positive.
Everything else predicts 0. These signals explain very little of the variance: most of the
activation depends on context the program does not read.
"""

READS = ()

COMMAS = {",", "，", "、"}
QUANTIFIERS = {"each", "every", "per", "map", "每个", "每", "各", "一", "一个", "任何"}
TIME_PARTICLES = {"时", "后", "時", "前", "之后", "以后", "之前", "而", "就是"}
CONNECTIVES = {"so", "thus", "therefore", "hence", "although", "however", "currently", "still"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    if tok in COMMAS:
        value -= 0.16
    if prev in QUANTIFIERS:
        value -= 0.8
    if tok in TIME_PARTICLES:
        value -= 0.9
    if tok.lower() in CONNECTIVES:
        value += 0.3
    return carry, value

"""Copula detector for the words that set up a predicate.

The component fires on forms of "to be" (is, was, were, be, been, are, being) that
introduce a description of a subject ("X is a ...", "was used ...", "can be examined").
It is strongest on was/were/been/be, and weaker on is/are; "am" is near zero. The value drops
to zero when the subject is an expletive or demonstrative ("there is", "this is",
"here are"), where no predicate about a thing follows.

Words that sit between the verb and its predicate ("is typically", "was also",
"is not", "is always") get a moderate value. The article "the" right after a be-form,
and the pronoun "it", are slightly negative. Everything else is 0, which is most of the
text: the component's activity is mostly small noise off these words.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# how strongly each form of "to be" fires (mean activation in the training text)
BE_STRENGTH = {
    "is": 1.5, "are": 1.9, "am": 0.3, "was": 2.2, "were": 2.4,
    "be": 2.0, "been": 2.5, "being": 2.0,
}
EXPLETIVE_SUBJECTS = {"there", "this", "that", "here"}
# adverbs and negation that sit between a be-form and its predicate
BETWEEN_ADVERBS = {
    "typically", "often", "usually", "originally", "also", "always", "never", "not",
    "primarily", "predominantly", "inherently", "historically", "generally", "very",
    "both", "only", "still", "already", "now", "then", "highly", "mostly",
}
ADVERB_VALUE = 1.5


def _word(text: str) -> str:
    return text.strip().lower()


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in BE_STRENGTH:
        if before in EXPLETIVE_SUBJECTS:
            return carry, 0.0
        return carry, BE_STRENGTH[word]
    if before in BE_STRENGTH:
        if word in BETWEEN_ADVERBS:
            return carry, ADVERB_VALUE
        if word == "the":
            return carry, -0.5
    if word == "it":
        return carry, -0.5
    return carry, 0.0
